head.script:
scwin.onpageload = function () {
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();
    dataList1.insertRow();


};

scwin.onpageunload = function () {

};

scwin.gridView1_onviewchange = function (info) {
    // alert("onviewchange");
	window.check_val1 = "onviewchage";
    console.log(info);
};

scwin.gridView1_oncellclick = function (row, col, colId) {
    // alert("oncellclick");
	window.check_val2 = "oncellclick";
    console.log(info);
};

    scwin.checkVal1 = function() {
        return window.check_val1 == "onviewchage";
    }

    scwin.checkVal2 = function() {
        return window.check_val2 == "oncellclick";
    }

	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gridView1_cell_0_0').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
